from wcommon import dims_G, dims_M, legend, notes, head, sched
LAYER = "E-INSECT"
ROWS=[(lambda s,x,y: s.device_dot(x,y,0.14,letter="IK"), "قاتل حشرات كهربائي UV 2×15W تغطية 30 م² - تعليق 2.20 م", "UV insect killer 2x15W"),
      (lambda s,x,y: s.circle(x,y,0.3,lw=5), "نطاق التغطية (نصف قطر 3 م)", "coverage radius 3 m")]
def _d(s,floor,pts):
    for p in pts: s.device_dot(*p,0.16,cover=3.0,letter="IK")
    (dims_G if floor=="G" else dims_M)(s,pts)
    legend(s,floor,"رموز قاتل الحشرات - LEGEND",ROWS)
    sched(s,floor,"جدول قاتل الحشرات",["البند","المواصفة","العدد"],[("IK","قاتل حشرات UV 2×15W شبكة كهربائية، هيكل ألمنيوم، صينية تجميع",f"{len(pts)}"),("تعليق","على ارتفاع 2.20 م من الأرضية بعيداً عن الطعام 1.5 م","-"),("تغذية","فيش 220V خلف الجهاز",f"{len(pts)}")])
    notes(s,floor,["يثبت الجهاز بعيداً عن أسطح تحضير الطعام بمسافة لا تقل عن 1.5 م وليس فوقها مباشرة.","الجهاز الأول خلف باب المدخل مباشرة لصد الحشرات الداخلة، وتنظف الصينية أسبوعياً.","الأبعاد الحمراء: موقع كل جهاز عن زوايا الجدران."],"ملاحظات")
def draw_G(s): _d(s,"G",[(12.0,35.4),(14.2,43.1),(14.2,45.6),(12.6,50.4),(11.5,54.35)]); head(s,"G","مخطط الناموسية (قاتل الحشرات) - الدور الأرضي: المدخل، نهاية الكاونتر، المطبخ، غسيل الأواني، التحضير.")
def draw_M(s): _d(s,"M",[(0.3,19.0),(8.5,20.0),(4.5,24.9),(4.2,25.4),(20.0,25.5),(13.5,25.2),(16.0,24.8)]); head(s,"M","مخطط الناموسية - الميزانين: الجلسات، الممر، مدخل الحمامات، المستودع، باب التجميد، المكاتب المفتوحة.")
